(
$payload := $state.context.LOCAL.schedules.maintenanceSchedule.edges.node.{
      "id": id,
      "assetId": assetId,
      "assetGroupId": assetGroupId,
      "checklistId":checklistId,
      "number": number,
      "active":active,
      "startAt": startAt,
      "nextScheduleAt": nextScheduleAt,
      "frequencyType": {"name":frequencyType.name},
      "checklist": {"name":checklist.number},
      "responsibility": {"name":responsibility.name},
      /* dont need this for create just eval, omit later*/
      "assetInServiceAt": asset.inServiceAt,
      "assetLastResetAt": asset.lastResetAt,
      "assetHours": asset.currentHours,
      "assetCycles": asset.currentCycles,
      "frequencyQuantity": frequencyQuantity
  };

/* FrequencyTypes
"Calendar","Monthly","Daily","Fixed Date By Month""Manual",
"Product Cycles","Production Hours","Workcenter Cycles"
*/
/* $manual := $filter($payload, function($v) { $v.frequencyType.name = "Manual"}); */
$workcenterCycles := $filter($payload, function($v) { $v.frequencyType.name = "Workcenter Cycles"});
$productionHours := $filter($payload, function($v) { $v.frequencyType.name = "Production Hours"});
$productCycles := $filter($payload, function($v) { $v.frequencyType.name = "Product Cycles"});
$yearly := $filter($payload, function($v) { $v.frequencyType.name = "Yearly" });
$monthly := $filter($payload, function($v) { $v.frequencyType.name = "Monthly"});
$weekly := $filter($payload, function($v) { $v.frequencyType.name = "Weekly"});
$daily := $filter($payload, function($v) { $v.frequencyType.name = "Daily"});


/* Fitler out records within tolerance  */
$filtered := {
  /*"Manual": $manual, No Fitler, but shouldnt be here  */
  "ProductionHours": $filter($ProductionHours, function($v) { $v.assetHours > $v.frequencyQuantity }),
  "ProductCycles": $filter($productCycles, function($v) { $v.assetCycles > $v.frequencyQuantity }),
  "WorkcenterCycles": $filter($productCycles, function($v) { $v.assetCycles > $v.frequencyQuantity }),
  "Yearly": $filter($yearly, function($v) {$moment().isAfter($v.nextScheduleAt ? $moment($v.nextScheduleAt) : $moment($v.startAt).add(1, 'year'))}),
  "Monthly": $filter($monthly, function($v) {$moment().isAfter($v.nextScheduleAt ? $moment($v.nextScheduleAt) : $moment($v.startAt).add(1, 'month'))}),
  "Weekly": $filter($weekly, function($v) {$moment().isAfter($v.nextScheduleAt ? $moment($v.nextScheduleAt) : $moment($v.startAt).add(1, 'week'))}),
  "Daily": $filter($daily, function($v) {$moment().isAfter($v.nextScheduleAt ? $moment($v.nextScheduleAt) : $moment($v.startAt).add(1, 'day'))})

};


$incomingData:= $map(
    $merge([
      $filtered.ProductionHours,
      $filtered.ProductCycles,
      $filtered.Yearly,
      $filtered.Monthly,
      $filtered.Weekly,
      $filtered.Daily
    ]),
    function($v) {
      $omit($v, ["assetInServiceAt", "assetLastResetAt", "assetHours", "assetCycles", "frequencyQuantity","nextScheduleAt"])
    }
  );


/* Filter out records that already have matching work orders */
$workOrderScheduleIds := $.workOrder.edges.node.maintenanceChecklist.schedules.edges.node.{"id":id };
$onlyNewWorkOrders := $filter($incomingData, function($v) {
  $count($filter($workOrderScheduleIds, function($w) { $w.id = $v.id })) = 0
}); 


/* Used to FOR loop through the items */ 
[$.{
    "REQUEST":{
    "DATA": $onlyNewWorkOrders,
    "ACTION": "GEN"
  }
}]

)

(
$current := workOrder.edges.node.maintenanceChecklist.schedules.edges.node.id;

/* filters out the existing WO items */
$payload := $state.context.LOCAL.schedules.maintenanceSchedule.edges.node[$not(id in [$current])].{
      "id": id,
      "assetId": assetId,
      "assetGroupId": assetGroupId,
      "checklistId":checklistId,
      "number": number,
      "active":active,
      "startAt": startAt,
      "nextScheduleAt": nextScheduleAt,
      "frequencyType": {"name":frequencyType.name},
      "checklist": {"name":checklist.number},
      "responsibility": {"name":responsibility.name},
      /* dont need this for create just eval, omit later*/
      "assetInServiceAt": asset.inServiceAt,
      "assetLastResetAt": asset.lastResetAt,
      "assetHours": asset.currentHours,
      "assetCycles": asset.currentCycles,
      "frequencyQuantity": frequencyQuantity
  };

$grouped := $groupBy([$payload], function ($v) { $v.frequencyType.name });

$woPayload := $each($grouped, function($v, $k) {(
  $nextAt := $k = "Daily" ? $moment().add(1, 'days')
      : $k = "Weekly" ? $moment().add(1, 'weeks')
      : $k = "Monthly" ? $moment().add(1, 'months')
      : $k = "Yearly" ? $moment().add(1, 'years')
      : $k = "Quarterly" ? $moment().add(0.25, 'year')
      : $k = "Bi-Annual" ? $moment().add(0.5, 'year'); 

  /* Calendar Functions */
  $k in ["Yearly", "Monthly", "Weekly", "Daily"] ? $map($v, function($item) {
     $merge([$item,{"startAt": $moment(),"nextScheduleAt": $nextAt}])
     })

  /* Threshold Functions */   
  : $k = "Production Hours" ? $v[assetHours > frequencyQuantity].[$merge([$v,{"startAt": $moment()}])]
  : $k in ["Product Cycles", "Workcenter Cycles"] ? $v.[assetCycles > frequencyQuantity].[$merge([$v,{"startAt": $moment()}])]

  )});

$filteredPayload := $woPayload ~> |$|{},["assetInServiceAt", "assetLastResetAt", "assetHours", "assetCycles", "frequencyQuantity","nextScheduleAt"]|;

$createPayload := [$filteredPayload.{"REQUEST":{"DATA": $,"ACTION": "GEN"}}];

$updatePayload := [$filteredPayload.{"update":{"startAt": startAt,"nextScheduleAt": nextScheduleAt},"where":{"id":id}}];


{"createPayload": $createPayload,"updatePayload": {"payload":$updatePayload}}

/* This should work need to test after closing WOs. Update Runs doesnt need { "payload":}, so remove after testing.
{"createPayload": $createPayload,"updatePayload": {"payload":$updatePayload}} */

)

{
  "LOCAL": {
    "generatedWO": $
  }
}

